#[derive(Debug, Clone, Copy)]
enum LeftDigit { U, W, F }

#[derive(Debug, Clone, Copy)]
enum RightDigit { C, C1, C2, V }

trait CounterDigit {
    fn num_heads_send(&self, n_recv: &BigUint) -> BigUint;
    fn max_heads_recv(&self, max_n_send: &BigUint) -> BigUint;

    /// update from receiving n heads, and return step count
    fn receive_heads(&mut self, n_heads: &BigUint) -> BigUint;

    fn to_block_symbol(&self) -> BlockSymbol;
    fn try_from_block_symbol(s: &BlockSymbol) -> Option<Self> where Self: Sized;
}

impl CounterDigit for LeftDigit {
    fn num_heads_send(&self, n_recv: &BigUint) -> BigUint {
        match &self {
            Self::U => n_recv / 2u8,
            Self::W => (n_recv + 1u8) / 2u8,
            Self::F => n_recv * 3u8,
        }
    }

    fn max_heads_recv(&self, max_n_send: &BigUint) -> BigUint {
        match &self {
            Self::U => max_n_send * 2u8 + 1u8,
            Self::W => max_n_send * 2u8,
            Self::F => max_n_send / 3u8,
        }
    }

    fn receive_heads(&mut self, n_heads: &BigUint) -> BigUint {
        match &self {
            Self::U => {
                let mut out = n_heads/2u8 * 7u8;
                if (n_heads % 2u8).to_u8().unwrap() == 1 {
                    out += 3u8;
                    *self = Self::W;
                }
                out
            },
            Self::W => {
                let mut out = n_heads/2u8 * 7u8;
                if (n_heads % 2u8).to_u8().unwrap() == 1 {
                    out += 4u8;
                    *self = Self::U;
                }
                out
            },
            Self::F => n_heads * 10u8,
        }
    }

    fn to_block_symbol(&self) -> BlockSymbol {
        use BlockSymbol as B;
        match &self {
            Self::U => B::U,
            Self::W => B::W,
            Self::F => B::F,
        }
    }

    fn try_from_block_symbol(s: &BlockSymbol) -> Option<LeftDigit> {
        use BlockSymbol as B;
        match s {
            B::U => Some(Self::U),
            B::W => Some(Self::W),
            B::F => Some(Self::F),
            _ => None,
        }
    }
}

impl CounterDigit for RightDigit {
    fn num_heads_send(&self, n_recv: &BigUint) -> BigUint {
        match &self {
            Self::C => n_recv / 3u8,
            Self::C1 => (n_recv + 1u8) / 3u8,
            Self::C2 => (n_recv + 2u8) / 3u8,
            Self::V => n_recv * 2u8,
        }
    }

    fn max_heads_recv(&self, max_n_send: &BigUint) -> BigUint {
        match &self {
            Self::C  => max_n_send * 3u8 + 2u8,
            Self::C1 => max_n_send * 3u8 + 1u8,
            Self::C2 => max_n_send * 3u8,
            Self::V => max_n_send / 2u8,
        }
    }

    fn receive_heads(&mut self, n_heads: &BigUint) -> BigUint {
        let mut c_idx: usize = match &self {
            Self::C => 0,
            Self::C1 => 1,
            Self::C2 => 2,
            Self::V => return n_heads * 7u8,
        };

        let mut n_steps = (n_heads / 3u8) * 10u8;
        const C_STEPS: [u8; 3] = [1, 5, 4];
        let rem = (n_heads % 3u8).to_u8().unwrap();
        for _ in 0..rem {
            n_steps += C_STEPS[c_idx as usize];
            c_idx = (c_idx + 1) % 3;
        }

        const C_DIGITS: [RightDigit; 3] = [RightDigit::C, RightDigit::C1, RightDigit::C2];
        *self = C_DIGITS[c_idx as usize];

        n_steps
    }

    fn to_block_symbol(&self) -> BlockSymbol {
        use BlockSymbol as B;
        match &self {
            Self::C  => B::C,
            Self::C1 => B::C1,
            Self::C2 => B::C2,
            Self::V  => B::V,
        }
    }

    fn try_from_block_symbol(s: &BlockSymbol) -> Option<RightDigit> {
        use BlockSymbol as B;
        match s {
            B::C => Some(Self::C),
            B::C1 => Some(Self::C1),
            B::C2 => Some(Self::C2),
            B::V => Some(Self::V),
            _ => None,
        }
    }
}

fn max_before_counter_overflow<T: CounterDigit>(half_tape: &Vec<BlockSymbol>) -> BigUint {
    let mut digits: Vec<T> = Vec::new();
    for s in half_tape.iter().rev() {
        if let Some(d) = T::try_from_block_symbol(s) {
            digits.push(d);
        } else {
            break;
        }
    }
    let mut n = BigUint::ZERO;
    for d in digits.iter().rev() {
        n = d.max_heads_recv(&n);
    }
    n
}

fn increase_counter<T: CounterDigit>(half_tape: &mut Vec<BlockSymbol>, n0: &BigUint) -> BigUint {
    let mut steps = BigUint::ZERO;
    let mut n = n0.clone();
    let mut digits: Vec<T> = Vec::new();
    while n > BigUint::ZERO {
        let mut d = T::try_from_block_symbol(&half_tape.pop().unwrap()).unwrap();
        let n_new = d.num_heads_send(&n);
        steps += d.receive_heads(&n);
        digits.push(d);
        n = n_new;
    }

    for d in digits.iter().rev() {
        half_tape.push(d.to_block_symbol());
    }
    steps
}

impl BlockSimulator {
    pub fn new(do_counter_accel: bool) -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L, U, Q],
            right_tape: vec![R],
            state: HigherState::Left,
            base_steps: BigUint::from(14u8),
            self_steps: 0,
            do_counter_accel
        }
    }

    pub fn new_with_tape(left_tape: Vec<BlockSymbol>, state: HigherState, right_tape: Vec<BlockSymbol>, do_counter_accel: bool) -> Self {
        Self {
            left_tape, right_tape, state,
            base_steps: BigUint::ZERO,
            self_steps: 0,
            do_counter_accel
        }
    }

    fn try_counter_accel(&mut self) -> Option<BigUint> {
        use BlockSymbol as B;

        if !matches!(self.left_tape.last(), Some(B::W | B::U)) ||
            !matches!(self.right_tape.last(), Some(B::C | B::C1 | B::C2)) ||
            !matches!(self.state, HigherState::Left | HigherState::Right){
                return None;
        }

        let max_n_left = max_before_counter_overflow::<LeftDigit>(&self.left_tape);
        let max_n_right = max_before_counter_overflow::<RightDigit>(&self.right_tape);
        // println!("{} {}", max_n_left, max_n_right);

        let n_incr = max_n_left.min(max_n_right);
        if n_incr == BigUint::ZERO {
            return None;
        }
        let steps = increase_counter::<LeftDigit>(&mut self.left_tape, &n_incr)
            + increase_counter::<RightDigit>(&mut self.right_tape, &n_incr);
        return Some(steps);
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        if self.do_counter_accel {
            if let Some(new_base_steps) = self.try_counter_accel() {
                self.base_steps += new_base_steps;
                self.self_steps += 1;
                return Ok(());
            }
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps += new_base_steps;
        self.self_steps += 1;
        Ok(())
    }

    fn is_reset_w_configuration(&self) -> bool {
        use BlockSymbol::*;
        use RunSymbolType::X;
        self.state == HigherState::RightWide &&
        (matches!(self.right_tape.as_slice(), [R, Run(X, _), P, C | C1 | C2]) ||
        matches!(self.right_tape.as_slice(), [R, Run(X, _), C | C1 | C2]))
    }

    fn is_reset_start(&self) -> bool {
        self.state == HigherState::RightWide && self.left_tape.len() == 1
    }
}

fn compare_accel_sim(n_steps: usize) {
    let mut sim = BlockSimulator::new(false);
    let mut sim_accel = BlockSimulator::new(true);

    for _ in 0..=n_steps {
        while sim.base_steps < sim_accel.base_steps {
            sim.step().unwrap();
        }
        println!("{sim_accel:>width$}", width=(sim.self_steps.checked_ilog10().unwrap_or(0) + 1) as usize);
        println!("{sim}");
        sim_accel.step().unwrap();
    }
}

